CREATE OR REPLACE FUNCTION public.check_sales_return_total()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_invoice_total numeric;
  v_prior_sum     numeric;
BEGIN
  IF NEW.invoice_id IS NULL THEN
