  END IF;
  PERFORM pg_advisory_xact_lock(hashtext(NEW.invoice_id::text));
  SELECT total_amount INTO v_invoice_total FROM public.tax_invoices WHERE id = NEW.invoice_id;
  IF v_invoice_total IS NULL THEN
