    RAISE EXCEPTION 'مجموع الاسترجاعات/إشعارات الدائن لهذه الفاتورة (%) يتجاوز إجماليها (%)',
      v_prior_sum + NEW.total_amount, v_invoice_total USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
